/**
 * The page for a query and its results (`design/archetypes/search-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Render,
  SlotOutlet,
  SlotTemplate,
  derived,
  isTemplate,
  presence,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/search-page.module.css'
import { EmptyState, type EmptyStateProps } from '../structure/EmptyState'
import { Inline, type InlineProps } from '../layout/Inline'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'

/** The page for a query and its results: the inputs it takes, by the React member's prop names. */
export interface SearchPageProps {
  description?: string
  /**
   * The query found nothing: the results region holds the empty state.
   */
  empty?: boolean
  /**
   * The empty state, required so the page always says what it shows when a query finds nothing.
   */
  emptyState: EmptyStateProps
  /**
   * A search is running: the results region is busy, and the last results stay in it.
   */
  pending?: boolean
  /**
   * The search landmark's name. A shell often has a search of its own, and two landmarks of one
   * kind are told apart only by their names.
   */
  searchLabel: string
  title: string
}

/** The page for a query and its results. */
@Component({
  selector: 'pm-search-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Render, SlotOutlet, SlotTemplate, EmptyState, Inline, PageHeader],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="filters" [pmSlotOf]="$"><ng-content select="[slot=filters]" /></ng-template>
<ng-template pmSlot="search" [pmSlotOf]="$"><ng-content select="[slot=search]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
[attr.data-empty]="e2()"
[attr.data-pending]="e3()"
data-member="search-page"
><pm-page-header
[title]="e4()"
[description]="e5()"
>@if (e6()) {<ng-container ngProjectAs="[slot=actions]"><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="actions" /></ng-container>}</pm-page-header>
@if (e7()) {<!-- search -->
<form
[attr.class]="e8()"
role="search"
[attr.aria-label]="e9()"
data-search-page-part="search"
[attr.novalidate]="e10()"
(submit)="h1($event)"
><ng-container [pmSlotOutlet]="'search'" [pmSlotOf]="$" />
@if (e11()) {<pm-inline
[gap]="e12()"
[wrap]="e13()"
><ng-container [pmSlotOutlet]="'filters'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}</form>} @else {<!-- search -->
<div
[attr.class]="e14()"
role="search"
[attr.aria-label]="e15()"
data-search-page-part="search"
><ng-container [pmSlotOutlet]="'search'" [pmSlotOf]="$" />
@if (e16()) {<pm-inline
[gap]="e17()"
[wrap]="e18()"
><ng-container [pmSlotOutlet]="'filters'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}</div>}
<!-- results -->
<div
[attr.class]="e19()"
[attr.aria-busy]="e20()"
data-search-page-part="results"
>@if (e21()) {<pm-empty-state
[icon]="e22()"
[title]="e23()"
[description]="e24()"
>@if (e26()) {<ng-container ngProjectAs="[slot=action]">@if (template(e25())) {<ng-container [pmRender]="e25()" />} @else {{{ e25() }}}</ng-container>}
@if (e28()) {<ng-container ngProjectAs="[slot=secondaryAction]">@if (template(e27())) {<ng-container [pmRender]="e27()" />} @else {{{ e27() }}}</ng-container>}</pm-empty-state>} @else {<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />}</div></div>`,
})
export class SearchPage {
  readonly description = input<SearchPageProps['description']>(undefined)
  /**
   * The query found nothing: the results region holds the empty state.
   */
  readonly empty = input<Exclude<SearchPageProps['empty'], undefined>, SearchPageProps['empty']>(
    false,
    { transform: (value: SearchPageProps['empty']) => (value === undefined ? false : value) },
  )
  /**
   * The empty state, required so the page always says what it shows when a query finds nothing.
   */
  readonly emptyState = input.required<SearchPageProps['emptyState']>()
  /**
   * A search is running: the results region is busy, and the last results stay in it.
   */
  readonly pending = input<
    Exclude<SearchPageProps['pending'], undefined>,
    SearchPageProps['pending']
  >(false, {
    transform: (value: SearchPageProps['pending']) => (value === undefined ? false : value),
  })
  /**
   * The search landmark's name. A shell often has a search of its own, and two landmarks of one
   * kind are told apart only by their names.
   */
  readonly searchLabel = input.required<SearchPageProps['searchLabel']>()
  readonly title = input.required<SearchPageProps['title']>()
  /**
   * Makes the landmark a real `<form>`, so Enter in the field submits. Without it the
   * application searches as the reader types.
   */
  readonly onSubmit = output<void>({ alias: 'submit' })
  protected readonly $ = useMember({
    events: ['submit'],
    props: {
      description: () => this.description(),
      empty: () => this.empty(),
      emptyState: () => this.emptyState(),
      pending: () => this.pending(),
      searchLabel: () => this.searchLabel(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly submit = derived(() => (event: Event) => {
    event.preventDefault()
    this.$.emit(this.onSubmit, 'onSubmit')
  })
  protected readonly template = isTemplate

  protected e1() {
    return styles.page
  }

  protected e2() {
    return this.$p.empty ? '' : undefined
  }

  protected e3() {
    return this.$p.pending ? '' : undefined
  }

  protected e4(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e5(): PageHeaderProps['description'] {
    return this.$p.description
  }

  protected e6() {
    return this.$.filled('actions')
  }

  protected e7() {
    return this.$.listening(this.onSubmit, 'onSubmit')
  }

  protected e8() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return styles.search
  }

  protected e9() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return this.$p.searchLabel
  }

  protected e10() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return presence(true)
  }

  protected h1($event: SubmitEvent): void {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return
    this.submit.value($event)
  }

  protected e11() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return this.$.filled('filters')
  }

  protected e12(): InlineProps['gap'] {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('filters')) return undefined as never
    return 3
  }

  protected e13(): InlineProps['wrap'] {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('filters')) return undefined as never
    return true
  }

  protected e14() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return styles.search
  }

  protected e15() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return this.$p.searchLabel
  }

  protected e16() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return this.$.filled('filters')
  }

  protected e17(): InlineProps['gap'] {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('filters')) return undefined as never
    return 3
  }

  protected e18(): InlineProps['wrap'] {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('filters')) return undefined as never
    return true
  }

  protected e19() {
    return styles.results
  }

  protected e20() {
    return this.$p.pending ? true : undefined
  }

  protected e21() {
    return this.$p.empty
  }

  protected e22(): EmptyStateProps['icon'] {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.icon
  }

  protected e23(): EmptyStateProps['title'] {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.title
  }

  protected e24(): EmptyStateProps['description'] {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.description
  }

  protected e25() {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.action
  }

  protected e26() {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.action !== undefined
  }

  protected e27() {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.secondaryAction
  }

  protected e28() {
    if (!this.$p.empty) return undefined as never
    return this.$p.emptyState.secondaryAction !== undefined
  }
}
